// ── CONFIG ── set once (stored encrypted).
const OPENAI_API_KEY = 'PASTE_OPENAI_API_KEY';

// Expects { audio_url } — a downloadable audio/video file URL. NOTE: the media
// pipeline must download the source video first; today only a thumbnail is stored,
// so this stays idle until video download is wired.
const src = $json.body || $json;
const audioUrl = src.audio_url;
if (!audioUrl) return { json: { text: '' } };

try {
  const bin = await this.helpers.httpRequest({ method: 'GET', url: audioUrl, encoding: 'arraybuffer' });
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/audio/transcriptions',
    headers: { Authorization: `Bearer ${OPENAI_API_KEY}` },
    body: {
      model: 'whisper-1',
      file: { value: Buffer.from(bin), options: { filename: 'audio.mp4', contentType: 'application/octet-stream' } }
    },
    formData: {
      model: 'whisper-1',
      file: { value: Buffer.from(bin), options: { filename: 'audio.mp4' } }
    },
    json: true
  });
  return { json: { text: res?.text ?? '' } };
} catch (e) {
  return { json: { text: '', error: String((e && e.message) || e) } };
}
